import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;  
  const percentage = parseFloat(input?.custom_graduated_pricing_and_unique_percentage?.percentage);
  const reactiveEnergyConsumption = parseFloat(input?.tsl_wo_work_order_attribute?.reactive_energy_consumption);
  const activeEnergyConsumption = parseFloat(input?.tsl_wo_work_order_attribute?.active_energy_consumption);

  console.log(billingItemCode)

  if (!billingItemCode) {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "parameter_billingItem_code for rule Reactiva not found"
      }
    }
  }

  let consumptionFactor = activeEnergyConsumption * (percentage/100);
  let consumptionReactive = reactiveEnergyConsumption - consumptionFactor;

  if (consumptionReactive < 0 ) {
    consumptionReactive = 0
  };


 // Fuente ÚNICA: arreglo de rangos
  const prices = Array.isArray(input?.custom_graduated_pricing_and_unique_percentage?.prices)
    ? input.custom_graduated_pricing_and_unique_percentage.prices
    : [];

  // Ordena por límite superior ascendente y mapea a {limite, precio}
  const filteredRanges = prices
    .slice()
    .sort(
      (a, b) =>
        Number(a.interval_high ?? 0) -
        Number(b.interval_high ?? 0)
    )
    .map((r) => ({
      limite:
        Number(r.interval_high) === 999999999 ||
        r.interval_high == null
          ? 999999999
          : Number(r.interval_high),
      precio: Number(r.base_price),
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        rule_description: 'prices for Reactiva not found',
        status: 'ERROR',
      }
    };
  }

  let limite_anterior = 0;
  let i = 0;

  for (; i < filteredRanges.length; i++) {
    const rango = filteredRanges[i];

    if (
      consumptionReactive >= limite_anterior &&
      consumptionReactive <= rango.limite &&
      rango.limite !== 999999999
    ) {
      break;
    } else if (
      consumptionReactive >= limite_anterior &&
      rango.limite === 999999999
    ) {
      break;
    }

    limite_anterior = rango.limite;
  }

  // Fallback si no se encontró (por si el consumo es mayor al último límite finito)
  if (i >= filteredRanges.length) i = filteredRanges.length - 1;

  let total_amount = filteredRanges[i].precio * consumptionReactive;

   console.log(filteredRanges[i].precio)
   console.log(consumptionReactive)
  console.log(total_amount)

 if (total_amount || total_amount == 0 ) {
    const billingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
    const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);
    billingItem.billing_item_amount = total_amount;

    return {
      ...input,
      result: {
          total_amount: total_amount,
          status: "OK",
          status_description: "Reactiva calculation rule completed"
        }
    };
  } else {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "The amount of the Reactiva rule could not be calculated."
      }
    };
  }
};
